/* @autogenerated */
package net.civeira.phylax.feature.oauth.consent.infrastructure.driven;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.consent.domain.ClientConsentSummary;
import net.civeira.phylax.feature.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The scope consents of the users stored with the generated repositories on h2. */
class ScopesConsentAdapterUnitTest {
  private OidcRepositories store;
  private ScopesConsentAdapter consents;
  private String clientUid;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    String tenant = store.tenant("acme");
    store.user(tenant, "alice", "alice@acme.test");
    clientUid = store.client(tenant, "web", "Web portal");
    String other = store.tenant("other");
    store.user(other, "alice", "alice@other.test");
    consents = new ScopesConsentAdapter(store.users(), store.tenants(), store.clients(),
        store.consents(), store.consentWriter());
  }

  private List<String> pending(String tenant, String user, String client, List<String> scopes) {
    return consents.pendingScopes(tenant, user, client, scopes).stream()
        .map(ScopePermission::getScope).toList();
  }

  @Test
  @DisplayName("The accepted scopes are not asked again, the new ones are")
  void accept_and_pending() {
    Assertions.assertEquals(List.of("openid", "email"),
        pending("acme", "alice", "web", List.of("openid", "email")));

    consents.storeAcceptedScopes("acme", "alice", "web", List.of("openid"));
    consents.storeApprovedScopes("acme", "alice", "web", List.of("openid", "profile"));

    Assertions.assertEquals(List.of("email"),
        pending("acme", "alice", "web", List.of("openid", "profile", "email")));
    Assertions.assertEquals(List.of("email"),
        consents.pendingApprovals("acme", "alice", "web", List.of("openid", "email"), List.of())
            .stream().map(ScopePermission::getScope).toList());
    Assertions.assertEquals(2, store.db().count("access_user_scope_consent", null),
        "An accepted scope is stored once");
  }

  @Test
  @DisplayName("A namesake in another tenant does not share the consents")
  void tenant_isolation() {
    consents.storeAcceptedScopes("acme", "alice", "web", List.of("openid"));

    Assertions.assertEquals(List.of("openid"), pending("other", "alice", "web", List.of("openid")));
    Assertions.assertTrue(consents.listGrantedByUser("other", "alice").isEmpty());
  }

  @Test
  @DisplayName("Unknown users, clients or empty requests store nothing and ask for everything")
  void unknown_parties() {
    Assertions.assertTrue(pending("acme", "alice", "web", List.of()).isEmpty());
    Assertions.assertEquals(List.of("openid"), pending("acme", "bob", "web", List.of("openid")));
    Assertions.assertEquals(List.of("openid"),
        pending("acme", "alice", "mobile", List.of("openid")));

    consents.storeAcceptedScopes("acme", "bob", "web", List.of("openid"));
    consents.storeAcceptedScopes("acme", "alice", "mobile", List.of("openid"));
    consents.storeAcceptedScopes("acme", "alice", "web", List.of());
    consents.withdrawScopes("acme", "bob", "web", List.of("openid"));
    consents.revokeClientConsent("acme", "bob", clientUid);
    consents.revokeScopeConsent("acme", "bob", clientUid, "openid");

    Assertions.assertEquals(0, store.db().count("access_user_scope_consent", null));
    Assertions.assertTrue(consents.listGrantedByUser("acme", "bob").isEmpty());
  }

  @Test
  @DisplayName("The granted scopes are listed by client with its name")
  void list_granted() {
    consents.storeAcceptedScopes("acme", "alice", "web", List.of("profile", "openid"));

    List<ClientConsentSummary> granted = consents.listGrantedByUser("acme", "alice");
    Assertions.assertEquals(1, granted.size());
    ClientConsentSummary summary = granted.get(0);
    Assertions.assertEquals(clientUid, summary.clientUid());
    Assertions.assertEquals("web", summary.clientId());
    Assertions.assertEquals("Web portal", summary.clientName().orElseThrow());
    Assertions.assertEquals(List.of("openid", "profile"), summary.grantedScopes());
    Assertions.assertTrue(summary.lastGrantedAt().isPresent());
  }

  @Test
  @DisplayName("A consent can be withdrawn by scope or for the whole client")
  void revoke() {
    consents.storeAcceptedScopes("acme", "alice", "web",
        List.of("openid", "profile", "email", "phone"));

    consents.revokeScopeConsent("acme", "alice", clientUid, "phone");
    consents.withdrawScopes("acme", "alice", "web", List.of("email"));
    consents.withdrawScopes("acme", "alice", "web", List.of());
    Assertions.assertEquals(List.of("openid", "profile"),
        consents.listGrantedByUser("acme", "alice").get(0).grantedScopes());

    consents.revokeClientConsent("acme", "alice", clientUid);
    Assertions.assertTrue(consents.listGrantedByUser("acme", "alice").isEmpty());
    Assertions.assertEquals(0, store.db().count("access_user_scope_consent", null));
  }
}
